extra_css:
/* Obsidian Sun surfaces: conchoidal black volcanic glass bordered by hammered gold and green jadeite inlays;
   hover ignites the solar gold bezel and jade corner accents. Headings gleam in hammered solar gold.
   Scoped to own surfaces only. */
html[data-atmo="obsidian"] .card, html[data-atmo="obsidian"] .panel, html[data-atmo="obsidian"] .gx-card {
  background: radial-gradient(125% 80% at 50% 0%, rgba(240,188,88,.08), rgba(64,175,120,.04) 45%, transparent 65%), linear-gradient(180deg, rgba(28,25,34,.90), rgba(8,7,9,.96));
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 rgba(250,224,160,.32), inset 0 0 0 1px rgba(240,188,88,.24), inset 0 0 0 3px rgba(48,140,96,.18), 0 18px 46px rgba(0,0,0,.80);
  transition: box-shadow .4s ease, transform .5s cubic-bezier(.2,1,.3,1), background .6s ease; }
html[data-atmo="obsidian"] .card:hover, html[data-atmo="obsidian"] .gx-card:hover {
  transform: translateY(-2px);
  background: radial-gradient(125% 80% at 50% 0%, rgba(250,224,160,.15), rgba(76,205,140,.07) 48%, transparent 68%), linear-gradient(180deg, rgba(34,30,42,.92), rgba(10,9,12,.97));
  box-shadow: inset 0 1px 0 rgba(255,238,186,.56), inset 0 0 0 1px rgba(240,188,88,.50), inset 0 0 0 3px rgba(72,190,132,.32), 0 0 28px rgba(240,188,88,.14), 0 22px 54px rgba(0,0,0,.84); }
html[data-atmo="obsidian"] h1, html[data-atmo="obsidian"] h2 { background: linear-gradient(180deg, #fff6dc, #f0bc58 52%, #9e7422); -webkit-background-clip: text; background-clip: text; color: transparent; }
html[data-atmo="obsidian"] h1 { filter: drop-shadow(0 2px 14px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(0,0,0,.85)); }

